import json
with open('/app/resources/treasury_bulletin_2020_12.json', 'r') as f:
    data = json.load(f)

# Look for state unemployment insurance data
def find_states(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            find_states(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_states(item, f'{path}[{i}]')

# Let's search for unemployment insurance taxes specifically
import pprint
def search(obj, target):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if target.lower() in k.lower():
                print(f'Found: {k}')
                print(f'Value: {v}')
            search(v, target)
    elif isinstance(obj, list):
        for item in obj:
            search(item, target)

search(data, 'unemployment')
